module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output reg [7:0] out
);

    wire [7:0] shift_4;
    wire [7:0] shift_2;
    wire [7:0] shift_1;

    assign shift_4 = {in[3:0], in[7:4]};
    assign shift_2 = {in[5:0], in[7:6]};
    assign shift_1 = {in[6:0], in[7]};

    assign out = (ctrl[2]) ? shift_4 :
                (ctrl[1]) ? shift_2 :
                (ctrl[0]) ? shift_1 : in;

endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
